import sys, random, subprocess

def naive(n, badlist, A, B):
    isbad=[False]*(n+1)
    for L,R in badlist:
        for j in range(L,R+1): isbad[j]=True
    r=[False]*(n+1); r[1]=True
    for p in range(2,n+1):
        if isbad[p]: continue
        for d in range(A,B+1):
            if p-d>=1 and r[p-d]:
                r[p]=True; break
    return "Yes" if r[n] else "No"

random.seed(7)
cases=0
for t in range(400):
    A=random.randint(1,6); B=random.randint(A,6)
    n=random.randint(2, 400 if t%2 else 40)
    # build disjoint bad intervals inside (1,n)
    intervals=[]
    cur=2
    while cur < n:
        if random.random()<0.6:
            L=cur; R=min(n-1, L+random.randint(0,random.choice([1,3,8,20,60])))
            intervals.append((L,R)); cur=R+1
        else:
            cur+=random.randint(1,random.choice([5,30,200]))
    inp=f"{n} {len(intervals)} {A} {B}\n"+"".join(f"{L} {R}\n" for L,R in intervals)
    out=subprocess.run([sys.executable,'solutions/abc388_f.py'],input=inp,capture_output=True,text=True).stdout.strip()
    exp=naive(n,intervals,A,B)
    cases+=1
    if out!=exp:
        print("MISMATCH",n,A,B,intervals,out,exp); break
else: print("all ok",cases)
