import random
def kuhn(A,l,r):
    idx=list(range(l,r+1)); m=len(idx)
    adj={i:[j for j in idx if A[j]>=2*A[i] and j!=i] for i in idx}
    match={}
    def try_k(u,vis):
        for v in adj[u]:
            if v in vis: continue
            vis.add(v)
            if v not in match or try_k(match[v],vis):
                match[v]=u; return True
        return False
    cnt=0
